// "Data last updated" line in the footer.
//
// docs/data/last-updated.json ({"crawled_at": "<ISO 8601>"}) is generated by
// scripts/update/generate_embeddings.mjs from the newest crawl time in
// data/update_state.json. It is a separate file because meta.json is a bare
// record list covered by the search-index checksums.

/** Format an ISO timestamp for display in the viewer's time zone, or return
 * null when it is missing or not a valid date. `timeZone` is only passed by
 * tests, so that their output does not depend on the machine. */
export function formatLastUpdated(iso, lang, timeZone) {
  if (typeof iso !== "string") return null;
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return null;
  try {
    return new Intl.DateTimeFormat(lang, {
      dateStyle: "medium",
      timeStyle: "short",
      ...(timeZone ? { timeZone } : {}),
    }).format(date);
  } catch {
    return null;
  }
}

/** Fill the footer element. Failures are silent: the line just stays hidden. */
export async function showLastUpdated(element, url, lang, template) {
  try {
    const res = await fetch(url);
    if (!res.ok) return;
    const { crawled_at: iso } = await res.json();
    const text = formatLastUpdated(iso, lang);
    if (!text) return;
    element.textContent = template(text);
    element.title = iso;
    element.hidden = false;
  } catch {
    /* optional information */
  }
}
